import {
  EventEnvelopeSchema,
  EventValidationError,
  type EventDefinition,
  type EventEnvelope,
} from './envelope.js';

/**
 * Schema registry (guideline §7: "schema registryと互換性テストをCIへ入れる").
 * The in-process registry is the source of truth for the JSON Schemas committed under
 * schemas/events/ (generated by `pnpm --filter @paas/event-contracts generate`), and CI fails
 * when the two diverge.
 */
export class EventRegistry {
  private readonly definitions = new Map<string, EventDefinition<string, unknown>>();

  register<TType extends string, TData>(definition: EventDefinition<TType, TData>): this {
    if (this.definitions.has(definition.type)) {
      throw new Error(`event type already registered: ${definition.type}`);
    }
    this.definitions.set(definition.type, definition);
    return this;
  }

  get(type: string): EventDefinition<string, unknown> | undefined {
    return this.definitions.get(type);
  }

  types(): string[] {
    return [...this.definitions.keys()].sort();
  }

  all(): EventDefinition<string, unknown>[] {
    return this.types().map((t) => this.definitions.get(t)!);
  }

  /**
   * Validates envelope + payload. Unknown event types are rejected: a consumer must opt in to
   * every type it handles, which is what makes versioning (order.created.v2) explicit.
   */
  parse(raw: unknown): EventEnvelope {
    const envelope = EventEnvelopeSchema.safeParse(raw);
    if (!envelope.success) {
      const type =
        typeof raw === 'object' && raw !== null ? (raw as { type?: unknown }).type : undefined;
      throw new EventValidationError(
        typeof type === 'string' ? type : undefined,
        envelope.error.issues,
      );
    }
    const definition = this.definitions.get(envelope.data.type);
    if (!definition) {
      throw new EventValidationError(envelope.data.type, [
        {
          code: 'custom',
          path: ['type'],
          message: 'unregistered event type',
          input: envelope.data.type,
        },
      ]);
    }
    const data = definition.dataSchema.safeParse(envelope.data.data);
    if (!data.success) {
      throw new EventValidationError(envelope.data.type, data.error.issues);
    }
    return { ...envelope.data, data: data.data };
  }

  /** Type-safe parse for a specific definition. */
  parseAs<TType extends string, TData>(
    definition: EventDefinition<TType, TData>,
    raw: unknown,
  ): EventEnvelope<TData> & { type: TType } {
    const parsed = this.parse(raw);
    if (parsed.type !== definition.type) {
      throw new EventValidationError(parsed.type, [
        {
          code: 'custom',
          path: ['type'],
          message: `expected ${definition.type}`,
          input: parsed.type,
        },
      ]);
    }
    return parsed as EventEnvelope<TData> & { type: TType };
  }
}
